args.Content:
Add-Type -AssemblyName System.IO.Compression.FileSystem

param (
    [string]$DocxPath
)

if (-not (Test-Path $DocxPath)) {
    Write-Error "File not found: $DocxPath"
    exit 1
}

$zip = [System.IO.Compression.ZipFile]::OpenRead($DocxPath)
$entry = $zip.GetEntry('word/document.xml')
if ($null -eq $entry) {
    Write-Error "word/document.xml not found in $DocxPath"
    $zip.Dispose()
    exit 1
}

$stream = $entry.Open()
$reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)
$xmlText = $reader.ReadToEnd()
$reader.Close()
$stream.Close()

# Also extract any images if there are any
$mediaEntries = $zip.Entries | Where-Object { $_.FullName -like 'word/media/*' }
$imageDir = Join-Path (Split-Path $DocxPath) "extracted_media_$([System.IO.Path]::GetFileNameWithoutExtension($DocxPath))"
if ($mediaEntries.Count -gt 0 -and -not (Test-Path $imageDir)) {
    New-Item -ItemType Directory -Path $imageDir -Force | Out-Null
    foreach ($m in $mediaEntries) {
        $dest = Join-Path $imageDir (Split-Path $m.FullName -Leaf)
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($m, $dest, $true)
    }
    Write-Output "Extracted $($mediaEntries.Count) images to $imageDir"
}

$zip.Dispose()

# Parse XML to extract text
$xml = [xml]$xmlText
$nsManager = New-Object System.Xml.XmlNamespaceManager($xml.NameTable)
$nsManager.AddNamespace("w", "http://schemas.openxmlformats.org/wordprocessingml/2006/main")

$paragraphs = $xml.SelectNodes("//w:p", $nsManager)
foreach ($p in $paragraphs) {
    $tNodes = $p.SelectNodes(".//w:t", $nsManager)
    $line = ($tNodes | ForEach-Object { $_.InnerText }) -join ""
    if ($line.Trim().Length -gt 0) {
        Write-Output $line
    }
}

