$bytes = [System.IO.File]::ReadAllBytes('C:\Users\Administrator\Desktop\淘晶驰git\USART屏幕\projects\NAFLD.HMI')

function Search-Pattern($pattern) {
    $patBytes = [System.Text.Encoding]::ASCII.GetBytes($pattern)
    $list = @()
    for ($i = 0; $i -lt $bytes.Length - $patBytes.Length; $i++) {
        $match = $true
        for ($j = 0; $j -lt $patBytes.Length; $j++) {
            if ($bytes[$i + $j] -ne $patBytes[$j]) {
                $match = $false
                break
            }
        }
        if ($match) {
            $list += $i
        }
    }
    return $list
}

$pages = @('jianyi', 'fankui', 'elec', 'jianyielec', 'fankuielec')
