// Find page elec
let pos = 0;
while ((pos = str.indexOf('objname.........elec', pos)) !== -1) {
    console.log(`Found page elec at ${pos}`);
    // Print 4000 characters from pos
    const slice = buf.subarray(pos, pos + 4000);
    let s = '';
    for (let i = 0; i < slice.length; i++) {
        const b = slice[i];
        if (b >= 32 && b <= 126) s += String.fromCharCode(b);
        else if (b === 10) s += '\n';
        else if (b > 127) s += `[${b.toString(16)}]`;
        else s += ' ';
    }
    console.log(s);
    pos += 20;
    break;
}

