547:  * @note   1. 持续从环形缓冲区提取完整帧并进入三级 switch-case 分发
548:  *         2. 治疗运行期按需节流刷新肺部动画（0~100）与剩余倒计时
549:  *         3. 每 10 秒刷新一次电池电量图标
550:  * @param  argument: FreeRTOS 任务参数（未使用）
551:  * @retval 无
552:  */
553: void ScreenTask(void const *argument)
554: {
555:     ScreenFrame_t frame;
556:     uint32_t tick_cnt = 0U;
557:     uint8_t  last_lung = 255U;      /* 上次已发送的肺部进度，用于变化检测节流 */
558:     uint16_t last_remain_s = 0xFFFFU;
559:     (void)argument;
560: 
561:     osDelay(50U);
562: 
563:     /* 启动初期显式关闭屏幕休眠与自动休眠定时器，确保屏幕始终常亮不熄屏 */
564:     BSP_Screen_SendRawCmd("sleep=0");
565:     BSP_Screen_SendRawCmd("usleep=0");
566: 
567:     for (;;)
568:     {
569:         /* 1. 排空并解析所有以 0xFF 0xFF 0xFF 结尾的完整上行数据帧 */
570:         while (BSP_Screen_ReadFrame(&frame))
571:         {
572:             if (frame.header == SCREEN_FRAME_HDR_CTRL || frame.header == SCREEN_FRAME_HDR_CUSTOM)
573:             {
574:                 if (frame.len >= 3U)
575:                 {
576:                     Screen_HandleCtrlFrame(&frame);
577:                 }
578:             }
579:             else if (frame.header == SCREEN_FRAME_HDR_TOUCH) /* 淘晶驰原生触摸帧兜底：0x65 [page] [comp] [event] */
580:             {
581:                 if (frame.len >= 4U)
582:                 {
583:                     Screen_HandleTouchFrame(frame.page, frame.control, frame.value);
584:                 }
585:             }
586:         }
587: 
588:         /* 2. 治疗运行中定时刷新肺部动画与剩余时间（值变化时才发送，降低串口负载） */
589:         if (g_app.running && !g_app.paused)
590:         {
591:             if (g_app.Breath_Mode != BREATH_MODE_OFF && g_app.lung_pct != last_lung)
592:             {
593:                 last_lung = g_app.lung_pct;
594:                 BSP_Screen_SetLungFill(last_lung);
595:             }
596: 
597:             if ((tick_cnt % 10U) == 0U) /* 每 200 ms 检查一次倒计时秒数变化 */
598:             {
599:                 uint32_t total_s = (uint32_t)g_app.timer_min * 60U;
600:                 uint32_t elap_s  = g_app.active_elapsed_ms / 1000U;
601:                 uint16_t rem_s   = (total_s > elap_s) ? (uint16_t)(total_s - elap_s) : 0U;
602:                 if (rem_s != last_remain_s)
603:                 {
604:                     last_remain_s = rem_s;
605:                     BSP_Screen_SetRemainTimeSec(rem_s);
606:                 }
607:             }
608:         }
609:         else
610:         {
611:             last_lung = 255U;
612:             last_remain_s = 0xFFFFU;
613:         }
614: 
615:         /* 3. 电池图标暂定不进行变化控制，下位机不参与赋值 */
616:         /*
617:         if ((tick_cnt % 500U) == 0U)
618:         {
619:             BSP_Screen_SetBattery(BSP_Power_GetBatteryPercent());
620:         }
621:         */
622: 
623:         tick_cnt++;
624:         osDelay(20U);
625:     }
626: }

