const fs = require('fs');
const xml = fs.readFileSync('c:/Users/Administrator/Desktop/淘晶驰git/media_20261120/word/document.xml', 'utf8');
const rels = fs.readFileSync('c:/Users/Administrator/Desktop/淘晶驰git/media_20261120/word/_rels/document.xml.rels', 'utf8');

const rMap = {};
const relMatches = rels.matchAll(/Id="([^"]+)"[^>]*Target="([^"]+)"/g);
for (const m of relMatches) {
    rMap[m[1]] = m[2];
}

const paras = xml.split('</w:p>');
paras.forEach((p, idx) => {
    let text = (p.match(/<w:t[^>]*>(.*?)<\/w:t>/g) || []).map(t => t.replace(/<[^>]+>/g, '')).join('');
    let imgIds = (p.match(/r:embed="([^"]+)"/g) || []).map(r => r.replace(/.*"([^"]+)"/, '$1'));
    let targets = imgIds.map(id => rMap[id] || id);
    if (text || targets.length) {
        console.log(`[${idx}] text: ${text}${targets.length ? ' | imgs: ' + targets.join(', ') : ''}`);
    }
});

