const fs = require('fs');
const path = require('path');

function walk(dir) {
    let list = [];
    for (let f of fs.readdirSync(dir)) {
        let full = path.join(dir, f);
        let stat = fs.statSync(full);
        if (stat.isDirectory()) list = list.concat(walk(full));
        else list.push(full);
    }
    return list;
}

