132: /**
133:  * @brief  从环形缓冲区非阻塞提取一帧完整串口屏报文（以连续 0xFF 0xFF 0xFF 结尾）
134:  * @param  frame: 输出参数，存放剥离帧尾后的完整帧内容及关键字段
135:  * @retval 1: 成功读出完整一帧；0: 缓冲区暂无完整帧
136:  */
137: uint8_t BSP_Screen_ReadFrame(ScreenFrame_t *frame)
138: {
139:     if (frame == NULL) return 0U;
140: 
141:     while (s_rx_tail != s_rx_head)
142:     {
143:         uint8_t b = s_rx_ring[s_rx_tail];
144:         s_rx_tail = (uint16_t)((s_rx_tail + 1U) % SCREEN_RX_RING_SIZE);
145: 
146:         /* 先存入临时组帧缓存，若超出最大帧长则丢弃残帧重新同步 */
147:         if (s_frame_len < SCREEN_FRAME_MAX_DATA)
148:         {
149:             s_frame_buf[s_frame_len++] = b;
150:         }
151:         else
152:         {
153:             s_frame_len = 0U;
154:             s_ff_cnt = 0U;
155:             continue;
156:         }
157: 
158:         /* 1. 统一协议定界：检测淘晶驰标准连续 3 个 0xFF 帧结束符 */
159:         if (b == 0xFFU)
160:         {
161:             s_ff_cnt++;
162:             if (s_ff_cnt >= 3U)
163:             {
164:                 if (s_frame_len > 3U)
165:                 {
166:                     /* 剥离末尾 3 字节 0xFF，输出完整有效载荷 */
167:                     uint8_t payload_len = (uint8_t)(s_frame_len - 3U);
168:                     memset(frame, 0, sizeof(*frame));
169:                     memcpy(frame->raw, s_frame_buf, payload_len);
170:                     frame->len     = payload_len;
171:                     frame->header  = frame->raw[0];
172:                     if (frame->header == 0xA5U) frame->header = 0x05U; /* 自动规格化为统一的 0x05 帧头 */
173:                     frame->page    = (payload_len > 1U) ? frame->raw[1] : 0U;
174:                     frame->control = (payload_len > 2U) ? frame->raw[2] : 0U;
175:                     frame->value   = (payload_len > 3U) ? frame->raw[3] : 0U;
176: 
177:                     s_frame_len = 0U;
178:                     s_ff_cnt = 0U;
179:                     return 1U;
180:                 }

