const fs = require('fs');

function readSym(id) {
    const path = `c:/Users/Administrator/Desktop/淘晶驰git/epro_extracted/SYMBOL/${id}.esym`;
    if (!fs.existsSync(path)) return null;
    return fs.readFileSync(path, 'utf8');
}

console.log("=== TLV3501 Symbol (88b8f64fd6f93bac) ===");
console.log(readSym('88b8f64fd6f93bac'));

console.log("\n=== STM32F405RGT6 Symbol (ce2d6c82b1b1410a) ===");
const mcuSym = readSym('ce2d6c82b1b1410a');
if (mcuSym) {
    const lines = mcuSym.split('\n');
    lines.forEach(l => {
        try {
            const obj = JSON.parse(l);
            // Look for PIN definitions
            if (obj[0] === 'PIN') {
                console.log(`Pin ${obj[1]} (${obj[2]}): name=${obj[3]}, pos=(${obj[4]}, ${obj[5]}), pinNum=${obj[6]}`);
            }
        } catch(e) {
            // maybe not json per line? let's see format
            if (l.includes('PB4') || l.includes('PC6') || l.includes('PA0') || l.includes('PB9') || l.includes('PB5')) {
                console.log(l.substring(0, 120));
            }
        }
    });
}

const fs = require('fs');

const mcuSymLines = fs.readFileSync('c:/Users/Administrator/Desktop/淘晶驰git/epro_extracted/SYMBOL/ce2d6c82b1b1410a.esym', 'utf8').split('\n');

let pins = {};
let currentPin = null;

for (let line of mcuSymLines) {
    line = line.trim();
    if (!line) continue;
    try {
        const obj = JSON.parse(line);
        if (obj[0] === 'PIN') {
            currentPin = obj[1];
            pins[currentPin] = { id: currentPin, x: obj[4], y: obj[5], name: '', number: '' };
        } else if (obj[0] === 'ATTR' && currentPin && obj[2] === currentPin) {
            if (obj[3] === 'NAME') pins[currentPin].name = obj[4];
            if (obj[3] === 'NUMBER') pins[currentPin].number = obj[4];
        }
    } catch(e) {}
}

console.log("=== MCU Pins of interest ===");
Object.values(pins).forEach(p => {
    if (p.name.includes('PB') || p.name.includes('PC') || p.name.includes('PA') || p.name.includes('PWM')) {
        console.log(`Pin ${p.number.padEnd(4)} Name: ${p.name.padEnd(16)} Rel: (${p.x}, ${p.y}) Abs: (${540 + p.x}, ${1820 + p.y})`);
    }
});

