        let pts = r[2];
        for (let i = 0; i < pts.length; i += 2) {
            let x = pts[i], y = pts[i+1];
            // Left side MCU pins are at x=450 or x=360 depending on pin length
            // Right side MCU pins are at x=630 or x=720
            // Symbol has pin line extending: in symbol, pin was pos=(-90, y) with length 10 or 20?
            // Let's check any wire point near (350..460, 1650..2000) or (620..730, 1800..2000)
            if ((x >= 350 && x <= 460 && y >= 1650 && y <= 2000) ||
                (x >= 620 && x <= 750 && y >= 1800 && y <= 2000)) {
                let net = wireNets[r[1]] || 'UNLABELED';
