for (let line of lines) {
    try {
        let r = JSON.parse(line.trim());
        if (r[0] === 'ATTR' && r[3] === 'NET') {
            netlabels.push({ name: r[4], x: r[7], y: r[8] });
        }
    } catch(e) {}
}

netlabels.forEach(nl => {
    if (nl.x >= 350 && nl.x <= 750 && nl.y >= 1600 && nl.y <= 2050) {
        // Find pin with closest distance
        let closest = null;
        let minDist = 999999;
        Object.values(pins).forEach(p => {
            let dist = Math.hypot(p.absX - nl.x, p.absY - nl.y);
            if (dist < minDist) {
                minDist = dist;
                closest = p;
            }
        });
        console.log(`Net ${nl.name.padEnd(16)} at (${nl.x}, ${nl.y}) -> Closest: Pin ${closest.number.padEnd(3)} (${closest.name.padEnd(16)}) dist=${minDist.toFixed(1)} pinPos=(${closest.absX}, ${closest.absY})`);
    }
});

