234:              * 周期 15000ms：前 10s 为疏波（基频 F），后 5s 为密波（5*F）
235:              */
236:             uint32_t t = wave_phase_ms % 15000U;
237:             s_gate_on = 1U;
238:             if (t < 10000U)
