259:         uint32_t vout_mv = BOOST_ADC_TO_MV(fb_raw);
260:         s_boost_mv[ch] = (uint16_t)vout_mv;
261: 
262:         if (elec_raw > s_elec_peak_adc[ch])
263:         {
264:             s_elec_peak_adc[ch] = elec_raw;
265:         }
266: 
267:         if (s_target_level[ch] == 0U)
268:         {
269:             s_current_level_f[ch] = 0.0f;
270:             s_boost_integral[ch] = 0.0f;
271:             set_boost_ccr(ch, 0U);
272:             set_cc_dac_ccr(ch, 0U);
273:             continue;
274:         }
275: 
276:         /* Electrode drop detection with 5000 ms debounce */
277:         if (s_gate_on)
278:         {
279:             if (s_elec_peak_adc[ch] < ELEC_VALID_ADC_THRESH)
280:             {
281:                 if (s_elec_drop_start_ms[ch] == 0U)
282:                 {
283:                     s_elec_drop_start_ms[ch] = now_ms;
284:                 }
285:                 else if ((now_ms - s_elec_drop_start_ms[ch]) >= STIM_ELEC_DROP_DEBOUNCE_MS)
286:                 {
287:                     s_elec_dropped[ch] = 1U;
288:                 }
289:             }
290:             else
291:             {
292:                 s_elec_drop_start_ms[ch] = 0U;
293:                 if (s_elec_dropped[ch])
294:                 {
295:                     s_elec_dropped[ch] = 0U;
296:                     s_current_level_f[ch] = 0.0f; /* Soft-start ramp on recovery */
297:                 }
298:             }
299:         }
300:         s_elec_peak_adc[ch] = 0U;
301: 
302:         if (s_elec_dropped[ch])
303:         {
304:             s_current_level_f[ch] = 0.0f;
305:             /* 脱落时恒流 DAC 保持微弱探测占空比（~1mA安全探针），保证电极重新贴附时能够被采样识别 */
306:             set_cc_dac_ccr(ch, 30U);
307:         }
308:         else
309:         {
310:             /* Soft-start ramp over STIM_ELEC_RECOVER_RAMP_MS (10ms step) */
311:             float target_f = (float)s_target_level[ch];
312:             float step = target_f * (10.0f / (float)STIM_ELEC_RECOVER_RAMP_MS);
313:             if (step < 0.02f) step = 0.02f;
314:             if (s_current_level_f[ch] < target_f)
315:             {
316:                 s_current_level_f[ch] += step;
317:                 if (s_current_level_f[ch] > target_f) s_current_level_f[ch] = target_f;
318:             }
319:             else
320:             {
321:                 s_current_level_f[ch] = target_f;
322:             }
323: 
324:             /* Update Constant-Current DAC PWM */
325:             uint32_t dac_ccr = (uint32_t)((s_current_level_f[ch] / (float)STIM_LEVEL_MAX) * (float)CC_DAC_CCR_30MA);
326:             set_cc_dac_ccr(ch, dac_ccr);
327:         }
328: 
329:         /* Closed-loop PI Boost regulator: 根据设定目标档位稳定升压 (7.5V ~ 30V)
330:          * 关键修复（问题7）：无论电极是否脱落，升压电路均维持设定档位目标电压稳定输出，
331:          * 确保 PA0 (TIM5_CH1) 始终产生 50kHz PWM，VOUT1 稳定升压而非死锁在 4.68V 二极管压降 */
332:         {
333:             float eff_level = (float)s_target_level[ch];
334:             float target_mv = (float)STIM_BOOST_MIN_MV +
335:                               (eff_level / (float)STIM_LEVEL_MAX) *
336:                               (float)(STIM_BOOST_MAX_MV - STIM_BOOST_MIN_MV);
337:             float err_v = (target_mv - (float)vout_mv) * 0.001f;
338:             float duty;
339:             s_boost_integral[ch] += err_v * 0.01f;
340:             if (s_boost_integral[ch] > 0.6f)  s_boost_integral[ch] = 0.6f;
341:             if (s_boost_integral[ch] < -0.2f) s_boost_integral[ch] = -0.2f;
342: 
343:             duty = 0.25f + err_v * 0.03f + s_boost_integral[ch] * 0.4f;
344:             if (duty < 0.0f)  duty = 0.0f;
345:             if (duty > 0.85f) duty = 0.85f;
346:             set_boost_ccr(ch, (uint32_t)(duty * (float)BOOST_PWM_PERIOD));
347:         }
348:     }
