352: {
353:     uint8_t ch;
354:     uint16_t raw;
355: 
356:     if (!s_enabled || !s_gate_on)
357:     {
358:         s_hb_state = HB_STATE_IDLE;
359:         s_cycle_tick_acc = 0U;
