364:     /* Sample electrode sense ADC during active pulse for reliable contact detection */
365:     if (s_hb_state == HB_STATE_POS_PULSE || s_hb_state == HB_STATE_NEG_PULSE)
366:     {
367:         for (ch = 0U; ch < STIM_CH_COUNT; ch++)
