414:                 for (ch = 0U; ch < STIM_CH_COUNT; ch++)
415:                 {
416:                     if (s_target_level[ch] > 0U)
417:                     {
418:                         hb_write_ch(ch, GPIO_PIN_RESET, GPIO_PIN_SET);
419:                     }
420:                     else
421:                     {
422:                         hb_write_ch(ch, GPIO_PIN_RESET, GPIO_PIN_RESET);
423:                     }
424:                 }
425:             }
426:             break;
427: 
428:         case HB_STATE_NEG_PULSE:
