const fs = require('fs');

const lines = fs.readFileSync('c:/Users/Administrator/Desktop/淘晶驰git/epro_extracted/SHEET/35380046f1c74da69bb44bcf1a4a638b/5.esch', 'utf8').split('\n');

let records = [];
for (let line of lines) {
    try {
        records.push(JSON.parse(line.trim()));
    } catch(e) {}
}

const comps = ['Q9', 'Q10', 'Q11', 'Q12', 'Q13', 'Q14', 'R10', 'R11', 'R12', 'R13', 'R14', 'R43', 'R44', 'AUDIO1', 'Q30', 'R70'];

let compMap = {};
records.forEach(r => {
    if (r[0] === 'ATTR' && r[3] === 'Designator' && comps.includes(r[4])) {
        let comp = records.find(c => c[0] === 'COMPONENT' && c[1] === r[2]);
        compMap[r[4]] = { id: r[2], des: r[4], type: comp ? comp[2] : '?', x: comp ? comp[3] : 0, y: comp ? comp[4] : 0 };
    }
});

console.log("=== H-Bridge CH1 Components ===");
console.log(compMap);

// For each component, let's find pins and connected wires
function findWiresNear(x, y, radius = 25) {
    let result = [];
    records.forEach(w => {
        if (w[0] === 'WIRE') {
            for (let seg of w[2]) {
